// Twilio signs: the full URL, then every POST parameter as sorted key+value.
// Mirrors twilio_signature() in tasks.py. The HMAC itself is done by the Crypto node, which
// works on n8n Cloud where the Code sandbox has no crypto module.
const WEBHOOK_PATH = '/webhook/hisaab/wf31-whatsapp';
const incoming = $input.first().json;
const headers = incoming.headers || {};
const params = incoming.body || {};
const signature = headers['x-twilio-signature'];
if (!signature) throw new Error('missing X-Twilio-Signature; refusing the request');
const proto = headers['x-forwarded-proto'] || 'http';
const host = headers['x-forwarded-host'] || headers.host;
let payload = proto + '://' + host + WEBHOOK_PATH;
for (const name of Object.keys(params).sort()) {
  const value = params[name];
  for (const one of Array.isArray(value) ? value : [value]) payload += name + one;
}
return [{ json: { payload, signature, params } }];

// Fail closed: a request we cannot authenticate must never reach core.
const item = $input.first().json;
if (item.expected !== item.signature) throw new Error('bad X-Twilio-Signature; dropping the message');
return [{ json: { params: item.params, verified: true } }];

// Who sent it, what they said, and whether it is a one-tap answer (2C.4).
// L1 replaces these numbers with the joined phones; unknown senders are dropped.
const PHONE_TO_MERCHANT = {
  'whatsapp:+919999999999': 'MID_DEMO_SAHANA',
};
const CORE = 'http://core:8000';
const FAKES = 'http://fakes:8200';

// 1 sale, 2 family, 3 my own money, 4 not sure - the WhatsApp set agreed in 2C.4.
// The app shows a fifth chip, loan/other, and voice or free text can still reach every value.
const BY_DIGIT = { '1': 'sale', '2': 'family', '3': 'own_money', '4': 'not_sure' };
const BY_WORD = {
  sale: 'sale', family: 'family', 'own money': 'own_money', 'my own money': 'own_money',
  loan: 'loan_or_gift', gift: 'loan_or_gift', 'not sure': 'not_sure',
  'ಮಾರಾಟ': 'sale', 'ಕುಟುಂಬ': 'family', 'ನನ್ನದೇ ಹಣ': 'own_money', 'ಖಚಿತವಿಲ್ಲ': 'not_sure',
  'बिक्री': 'sale', 'परिवार': 'family', 'मेरा अपना पैसा': 'own_money', 'पक्का नहीं': 'not_sure',
};

const params = $input.first().json.params || {};
const from = params.From || '';
const merchant_id = PHONE_TO_MERCHANT[from];
if (!merchant_id) throw new Error('unknown sender ' + from + '; not a merchant we know');

const text = (params.Body || '').trim();
const mediaCount = parseInt(params.NumMedia || '0', 10);
const answer = BY_DIGIT[text] || BY_WORD[text.toLowerCase()] || null;

// A voice note is deliberately not handled yet: the STT fake arrives with the L1
// cassettes (handoff H5). Until then a voice note is treated as free text.
return [{ json: {
  core: CORE,
  fakes: FAKES,
  merchant_id,
  from,
  text,
  has_media: mediaCount > 0,
  media_url: params.MediaUrl0 || null,
  answer,
  route: answer ? 'answer' : 'intent',
  language: 'kn-IN',
  sim_at: new Date().toISOString(),
} }];

// Answer the question the merchant is replying to: the oldest open one, which is what
// M2 shows as "1 of 3". ClaimAnsweredPayload takes exactly one of raw_text or
// media_sha256, so a typed or numbered reply sends raw_text.
const inbound = $('Normalise').first().json;
const questions = ($input.first().json.items) || [];
if (!questions.length) throw new Error('no open question for ' + inbound.merchant_id);
const question = questions[0];
return [{ json: {
  ...inbound,
  question_id: question.question_id,
  txn_id: question.txn_id,
  question_text: question.question,
  language: question.language || inbound.language,
  claim: {
    merchant_id: inbound.merchant_id,
    txn_id: question.txn_id,
    action: 'answered',
    claim: {
      question_id: question.question_id,
      answer: inbound.answer,
      raw_text: inbound.text,
      language: question.language || inbound.language,
    },
    sim_at: inbound.sim_at,
  },
} }];

// Acknowledge in the merchant's language. Templates move to i18n in task 5.4; the text
// never carries a number the LLM produced.
const answered = $('Build claim').first().json;
const THANKS = {
  'kn-IN': 'ಧನ್ಯವಾದಗಳು. ದಾಖಲಿಸಲಾಗಿದೆ.',
  'hi-IN': 'धन्यवाद। दर्ज कर लिया गया है।',
  'en-IN': 'Thank you. Recorded.',
};
return [{ json: {
  merchant_id: answered.merchant_id,
  text: THANKS[answered.language] || THANKS['en-IN'],
  language: answered.language,
  channel: 'whatsapp',
  to: answered.from,
  conversation_id: 'wf31-' + answered.merchant_id,
  sim_at: answered.sim_at,
} }];

// Free text. The refusal for hide_income is fixed and never generated (task 9.2).
const inbound = $('Normalise').first().json;
const raw = JSON.stringify($input.first().json || {}).toLowerCase();
const intent = raw.includes('hide_income') ? 'hide_income' : 'other';
const REPLY = {
  hide_income: "I can't help hide income. I can help you keep accurate records.",
  other: 'Reply 1 sale · 2 family · 3 my own money · 4 not sure',
};
return [{ json: {
  merchant_id: inbound.merchant_id,
  text: REPLY[intent],
  language: inbound.language,
  channel: 'whatsapp',
  to: inbound.from,
  conversation_id: 'wf31-' + inbound.merchant_id,
  sim_at: inbound.sim_at,
} }];
